def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class Point(Point):
        __slots__ = ()
        _fformat = "(%s)" % ", ".join(["%r" if f is None else "%s=%%r" % f for f in fields])
        if fields:
            for i, a in enumerate(fields):
                if a is not None:
                    vars()[a] = property(itemgetter(i))
            del i, a
        def __init__(self, *args, **kwargs):
            if len(args) == 1 and len(kwargs) == 0 and isinstance(args[0], (tuple, list)):
                args = args[0]
            super().__init__(*args, **kwargs)
        def __repr__(self):
            return "Point(%s)" % ", ".join(["%s=%r" % (f, getattr(self, f)) for f in fields])
        def __eq__(self, other):
            return all(getattr(self, f) == getattr(other, f) for f in fields)
        def __ne__(self, other):
            return not self.__eq__(other)
        def __hash__(self):
            return hash(tuple(getattr(self, f) for f in fields))
        def __reduce__(self):
            return (point_type, (name, fields, srid_map), self.__getstate__())
        def __getstate__(self):
            return tuple(getattr(self, f) for f in fields)
        def __setstate__(self, state):
            for i, f in enumerate(fields):
                setattr(self, f, state[i])
    return Point

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    :param message: The message to be displayed when the deprecated function is called.
    :type message: str

    """
    def decorator(func):
        @functools.wraps(func)
