def difference(d1, d2, level=-1):
    if level == 0:
        return d1
    result = {}
    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        elif level == -1:
            result[key] = d1[key]
        elif isinstance(d1[key], dict):
            result[key] = difference(d1[key], d2[key], level - 1)
    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, (list, tuple)):
        coord = [coord]
    if len(coord) != self.ndim:
        raise ValueError("coord must have length equal to the number of dimensions")
    if not isinstance(weight, (int, float)):
        raise ValueError("weight must be a number")
    if weight <= 0:
        raise ValueError("weight must be positive")

    for i, c in enumerate(coord):
        if c < self.edges[i][0] or c >= self.edges[i][-1]:
            return

    self.values[i] += weight
    self.sum += weight

    if self.sum > self.max_sum:
        self.max_sum = self.sum

    if self.sum > self.max_values[i]:
        self.max_values[i] = self.sum

    if self.sum > self.max_coords[i]:
        self.max_coords[i] = coord[i]

    if self.sum > self.max_weights[i]:
        self.max_weights[i] = weight

    if self.sum > self.max_coords_weights[i]:
        self.max_coords_weights[i] = (coord[i], weight)

    if self.sum > self.max_values_weights[i]:
        self.max_values_weights[i] = (self.values[i], weight)

    if self.sum > self.max_values_coords[i]:
        self.max_values_coords[i] = (self.values[i], coord[i])

    if self.sum > self.max_values_coords_weights[i]:
        self.max_values_coords_weights[i] = (self.values[i], coord[i], weight)

