def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Check if inventory is a dictionary
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Check if inventory has the required fields
    required_fields = ["type", "version", "items"]
    for field in required_fields:
        if field not in inventory:
            raise ValueError(f"Inventory is missing required field: {field}")

    # Check if type is valid
    if extract_spec_version:
        if "type" not in inventory:
            raise ValueError("Inventory is missing required field: type")
        if not isinstance(inventory["type"], str):
            raise ValueError("Inventory type must be a string")
        if inventory["type"] not in self.spec_versions:
            raise ValueError(f"Inventory type {inventory['type']} is not supported")
    else:
        if "type" in inventory and not isinstance(inventory["type"], str):
            raise ValueError("Inventory type must be a string")

    # Check if version is valid
    if "version" not in inventory:
        raise ValueError("Inventory is missing required field: version")
    if not isinstance(inventory["version"], str):
        raise ValueError("Inventory version must be a string")
    if inventory["version"] not in self.spec_versions:
        raise ValueError(f"Inventory version {inventory['version']} is not supported")

    # Check if items is a list
    if "items" not in inventory:
        raise ValueError("Inventory is missing required field: items")
    if not isinstance(inventory["items"], list):
        raise ValueError("Inventory items must be a list")

    # Check if items are valid
    for item in inventory["items"]:
        if not isinstance(item, dict):
            raise ValueError("Inventory item must be a dictionary")
        if "name" not in item:
            raise ValueError("Inventory item is missing required field: name")
        if not isinstance(item["name"], str):
            raise ValueError("Inventory item name must be a string")
        if "quantity" not in item:
            raise ValueError("Inventory item is missing required field: quantity")
        if not isinstance(item["quantity"], int):
            raise ValueError("Inventory item quantity must be an integer")

    # If we made it this far, the inventory is valid
    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest_file in manifest_files:
        with open(manifest_file, "r") as f:
            manifest = json.load(f)
        for digest in manifest["digests"]:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} is not used in any APK")
    for digest in digests_used:
        if digest not in manifest["digests"]:
            raise ValueError(f"Digest {digest} is not present in any manifest")
    return True

def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise ValueError("Input prior is not an InventoryValidator object")

        if self.inventory.size != prior.inventory.size:
            raise ValueError("Inventories have different sizes")

        for i in range(self.inventory.size):
            if self.inventory[i] != prior.inventory[i]:
                raise ValueError("Inventories are not equal")

        if self.priors.size != prior.priors.size:
            raise ValueError("Priors have different sizes")

        for i in range(self.priors.size):
            if self.priors[i] != prior.priors[i]:
                raise ValueError("Priors are not equal")

        if self.constraints.size != prior.constraints.size:
            raise ValueError("Constraints have different sizes")

        for i in range(self.constraints.size):
            if self.constraints[i] != prior.constraints[i]:
                raise ValueError("Constraints are not equal")

        if self.param_array.size != prior.param_array.size:
            raise ValueError("Parameter arrays have different sizes")

        for i in range(self.param_array.size):
            if self.param_array[i] != prior.param_array[i]:
                raise ValueError("Parameter arrays are not equal")

        if self.log_prior != prior.log_prior:
            raise ValueError("Log priors are not equal")

        if self.log_jacobian != prior.log_jacobian:
            raise ValueError("Log Jacobians are not equal")

        return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    logical_path_map = {}

    for content_file in inventory.get_content_files(version):
        logical_path = content_file.get_logical_path()
        if logical_path not in logical_path_map:
            logical_path_map[logical_path] = set()
        logical_path_map[logical_path].add(content_file)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")

    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list")

    for file in fixity:
        if file not in manifest_files:
            raise ValueError("File {} is not listed in the manifest".format(file))

    for file in manifest_files:
        if file not in fixity:
            raise ValueError("File {} is not listed in the fixity block".format(file))

    for file in fixity:
        if not isinstance(fixity[file], dict):
            raise ValueError("Fixity for file {} must be a dictionary".format(file))

        if not isinstance(fixity[file]["hash"], str):
            raise ValueError("Hash for file {} must be a string".format(file))

        if not isinstance(fixity[file]["size"], int):
            raise ValueError("Size for file {} must be an integer".format(file))

    return fixity

def files_list(path):
    """
    Return the files in `path`
    """
    files = []
    for file in os.listdir(path):
        if os.path.isfile(os.path.join(path, file)):
            files.append(file)
    return files

def fix_namespace_prefix_w(content):
