def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, And):
            if arg.left == arg.right:
                new_args.append(arg.left)
            elif arg.left == Not(arg.right):
                new_args.append(arg.left)
            else:
                new_args.append(arg)
        elif isinstance(arg, Or):
            if arg.left == arg.right:
                new_args.append(arg.left)
            elif arg.left == Not(arg.right):
                new_args.append(arg.left)
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        with open(VERSION_PATH, 'r') as rfile:
            contents = rfile.read().strip()

        _, version = contents.split('=')
        version = version.strip()

        # Remove quotes
        return version.strip('"\'')
    except Exception as e:
        return "default"

def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if not pieces or not style:
        raise ValueError("pieces and style must be provided")

    if style not in ["major", "minor", "patch"]:
        raise ValueError("style must be one of 'major', 'minor', or 'patch'")

    if not isinstance(pieces, list):
        raise TypeError("pieces must be a list")

    if not all(isinstance(piece, str) for piece in pieces):
        raise TypeError("pieces must be a list of strings")

    if len(pieces) != 3:
        raise ValueError("pieces must have exactly 3 elements")

    if style == "major":
        return pieces[0]
    elif style == "minor":
        return pieces[1]
    else:
        return pieces[2]

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if '+' not in pieces:
        return '+'
    else:
        return '.'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    output = None
    try:
        output = subprocess.check_output(commands, args, cwd=cwd, verbose=verbose, hide_stderr=hide_stderr, env=env, stderr=subprocess.STDOUT, shell=False)
    except subprocess.CalledProcessError:
        msg = "couldn't run command\n{}".format(commands)
        raise ProgramError(msg)
    return output

def register_vcs_handler(vcs, method):  # type: (str, str) -> typing.Callable
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Args:
        validate_objects (bool): Whether to validate objects in the hierarchy.
        check_digests (bool): Whether to check object digests.
        show_warnings (bool): Whether to show warnings.

    Returns:
        num_objects (int): Number of objects checked.
        good_objects (int): Number of objects checked that were found to be valid.
    """
    # Initialize variables
    num_objects = 0
    good_objects = 0

    # Iterate over the hierarchy
    for obj in self.hierarchy:
        num_objects += 1

        # Validate the object
        if validate_objects:
            if not self.validate_object(obj):
                if show_warnings:
                    print(f"Warning: Object {obj} is invalid.")
            else:
                good_objects += 1

        # Check the object digest
        if check_digests:
            if not self.check_digest(obj):
                if show_warnings:
                    print(f"Warning: Object {obj} has an invalid digest.")

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.startswith("0"):
        return str(int(version) + 1)
    else:
        return str(int(version) + 1).zfill(len(version))

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for version_dir in version_dirs:
        inventory_path = os.path.join(self.root_dir, version_dir, "inventory.json")
        if not os.path.exists(inventory_path):
            raise ValueError(f"Inventory file not found for version {version_dir}")
        with open(inventory_path, "r") as f:
            inventory = json.load(f)
        if not inventory:
            raise ValueError(f"Inventory file is empty for version {version_dir}")
        if version_dir == "1":
            self.root_inventory = inventory
        else:
            self.version_inventories[version_dir] = inventory
            self.different_content_digests.update(
                set(inventory.keys()) - set(self.root_inventory.keys())
            )

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not path:
        raise ValueError("Path is required")

    if not os.path.exists(path):
        raise FileNotFoundError(f"Path {path} does not exist")

    if os.path.isdir(path):
        if os.path.isfile(os.path.join(path, "0=*")):
            return "root"
        else:
            return "object"
    else:
        return "file"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise BugsyException("Please pass in a dictionary of params")
    if not isinstance(bug_ids, list):
        raise BugsyException("Please pass in a list of bug IDs")
    for bug_id in bug_ids:
        if not isinstance(bug_id, int):
            raise BugsyException("Please pass in a list of bug IDs as integers")
    for param in params:
        if not isinstance(param, str):
            raise BugsyException("Please pass in a dictionary of params with string keys")
    for bug_id in bug_ids:
        result = self.request('bug/%s' % bug_id, 'PUT', json=params)
        if 'error' in result:
            raise BugsyException(result['message'])
    return params

