def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """

    if other is None:
        return self._scale
    elif isinstance(other, (int, float)):
        if self._scale == 0:
            raise LenaValueError("Cannot rescale graph with unknown scale")
        self._scale = other
        for field in self._fields:
            if field.endswith("_error"):
                field_name = field[:-6]
                if field_name in self._fields:
                    self._fields[field_name] *= other
            else:
                self._fields[field] *= other
    else:
        raise TypeError("other must be a numeric value")

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(candidate, iface):
        raise TypeError("Candidate must be an instance of %s" % iface)
    if not hasattr(candidate, "__dict__"):
        raise TypeError("Candidate must have a __dict__ attribute")
    for attr in iface.__dict__:
        if not hasattr(candidate, attr):
            raise TypeError("Candidate is missing attribute %s" % attr)
        if not callable(getattr(candidate, attr)):
            raise TypeError("Attribute %s must be callable" % attr)
    return True

