def validate_from_content(spec_content):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    try:
        spec = yaml.load(spec_content, Loader=yaml.FullLoader)
    except yaml.YAMLError as e:
        raise IRValidatorException("Invalid YAML content: {}".format(e))
    except Exception as e:
        raise IRValidatorException("Error loading spec content: {}".format(e))

    required_fields = ["name", "version", "description", "inputs", "outputs"]
    for field in required_fields:
        if field not in spec:
            raise IRValidatorException("Missing required field '{}' in spec".format(field))

    return spec

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if yaml_file is None:
        raise ValueError("yaml_file argument must be supplied")

    try:
        with open(yaml_file, 'r') as f:
            data = yaml.load(f)
    except Exception as e:
        raise IRValidatorException(f"There was a problem loading the YAML file: {e}")

    if not data:
        raise IRValidatorException(f"The YAML file is empty")

    required_fields = ['name', 'description', 'version']
    for field in required_fields:
        if field not in data:
            raise IRValidatorException(f"The YAML file is missing the required field: {field}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'include' in parser_dict:
        for include in parser_dict['include']:
            if isinstance(include, str):
                include_dict = self._load_spec_file(include)
                parser_dict.update(include_dict)
            elif isinstance(include, dict):
                parser_dict.update(include)
            else:
                raise ValueError(f'Invalid include directive: {include}')
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    spec_defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError('Unable to build default for non-Option type')

        # if there is a default set, add it to the spec_defaults dict
        if not isinstance(arg.default, NoDefault):
            spec_defaults[arg.name] = arg.default

        # if we have a dict option, build the spec_defaults for its scheme.
        # if any spec_defaults exist, use them.
        if isinstance(arg, DictOption):
            if arg.scheme:
                b = arg.scheme.build_spec_defaults()
                if b:
                    spec_defaults[arg.name] = b
    return spec_defaults

