def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # get the function argspec
    argspec = getargspec(self)

    func_defaults = argspec.defaults or tuple()
    defaults = (Required,) * (len(argspec.args) - len(func_defaults)) + func_defaults
    for index, arg_name in enumerate(argspec.args):
        arg_value = args[index] if index < len(args) else kwargs.get(arg_name)
        if arg_value is not None:
            continue
        if defaults[index] is not Required:
            continue
        abort("Missing required argument: {}".format(arg_name))

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg, length in args.items():
        if len(arg) > length:
            raise ValueError(f"Argument {arg} is longer than the specified length of {length}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if arg_name in self.choices:
            if arg_value not in self.choices[arg_name]:
                raise ValueError(f"Invalid value for argument '{arg_name}': {arg_value}. Must be one of {self.choices[arg_name]}")
    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if len(args) != 2:
        raise TypeError("Expected 2 arguments, got {}".format(len(args)))
    if not isinstance(args[0], (int, float)):
        raise TypeError("First argument must be a number")
    if not isinstance(args[1], (int, float)):
        raise TypeError("Second argument must be a number")
    if args[0] > args[1]:
        raise ValueError("First argument must be less than or equal to second argument")
    return args

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith("--"):
            control_args[arg] = args[arg]
        elif arg.startswith("-"):
            nested_args[arg] = args[arg]
        else:
            custom_args[arg] = args[arg]

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not vars_dict:
        return vars_dict
    if not extra_vars:
        return vars_dict
    for extra_var in extra_vars:
        if extra_var not in vars_dict:
            vars_dict[extra_var] = extra_vars[extra_var]
        else:
            vars_dict[extra_var] = merge_extra_vars(vars_dict[extra_var], extra_vars[extra_var])
    return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = get_plugin_spec(plugin_dir)
    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                flatten_dict[f"{key}.{sub_key}"] = sub_value
        else:
            flatten_dict[key] = value
    return flatten_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if not os.environ.get('CONFIG_PATH'):
        os.environ['CONFIG_PATH'] = self.config_path
    return self.config_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
